{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 입구에 목줄 걸어 둘 곳이나 잠깐 기다릴 자리를 만들어 주는 규정",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제22조의2 제2항은 시장이 공원 내 화장실, 매점 등에 반려동물의 목줄 등을 걸어두거나 반려동물이 따로 머무를 수 있는 공간을 설치하도록 노력하여야 한다고 정하고 있습니다. 다만 시민들의 이동과 안전에 지장을 초래하지 아니하도록 하여야 합니다. 따라서 공원 입구에 목줄 걸이 공간이나 대기 자리를 마련하도록 하는 규정이 존재합니다.",
          "b_ids": "도시공원:제22조의2제2항, 도시공원:제22조의2제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
